from collections import defaultdict, deque

def alien_order(words):
    graph = {ch: set() for word in words for ch in word}
    indegree = {ch: 0 for ch in graph}
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return ''
        for x, y in zip(a, b):
            if x != y:
                if y not in graph[x]:
                    graph[x].add(y)
                    indegree[y] += 1
                break
    queue = deque([ch for ch, deg in indegree.items() if deg == 0])
    out = []
    while queue:
        ch = queue.popleft()
        out.append(ch)
        for nxt in graph[ch]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)
    return ''.join(out) if len(out) == len(indegree) else ''

