export function alienOrder(words: string[]): string {
  const graph = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();
  for (const word of words) for (const ch of word) { graph.set(ch, graph.get(ch) ?? new Set()); indegree.set(ch, indegree.get(ch) ?? 0); }
  for (let i = 0; i + 1 < words.length; i += 1) {
    const a = words[i], b = words[i + 1];
    if (a.length > b.length && a.startsWith(b)) return '';
    for (let j = 0; j < Math.min(a.length, b.length); j += 1) if (a[j] !== b[j]) { if (!graph.get(a[j])!.has(b[j])) { graph.get(a[j])!.add(b[j]); indegree.set(b[j], indegree.get(b[j])! + 1); } break; }
  }
  const queue = [...indegree.entries()].filter(([, deg]) => deg === 0).map(([ch]) => ch);
  const out: string[] = [];
  for (let i = 0; i < queue.length; i += 1) {
    const ch = queue[i];
    out.push(ch);
    for (const next of graph.get(ch) ?? []) {
      indegree.set(next, indegree.get(next)! - 1);
      if (indegree.get(next) === 0) queue.push(next);
    }
  }
  return out.length === indegree.size ? out.join('') : '';
}

