String alienOrder(String[] words) {
  Map<Character, Set<Character>> graph = new HashMap<>();
  Map<Character, Integer> indegree = new HashMap<>();
  for (String word : words) for (char ch : word.toCharArray()) { graph.putIfAbsent(ch, new HashSet<>()); indegree.putIfAbsent(ch, 0); }
  for (int i = 0; i + 1 < words.length; i++) {
    String a = words[i], b = words[i + 1];
    if (a.length() > b.length() && a.startsWith(b)) return "";
    for (int j = 0; j < Math.min(a.length(), b.length()); j++) if (a.charAt(j) != b.charAt(j)) { if (graph.get(a.charAt(j)).add(b.charAt(j))) indegree.merge(b.charAt(j), 1, Integer::sum); break; }
  }
  Queue<Character> queue = new ArrayDeque<>();
  for (Map.Entry<Character, Integer> e : indegree.entrySet()) if (e.getValue() == 0) queue.add(e.getKey());
  StringBuilder out = new StringBuilder();
  while (!queue.isEmpty()) { char ch = queue.remove(); out.append(ch); for (char next : graph.get(ch)) if (indegree.merge(next, -1, Integer::sum) == 0) queue.add(next); }
  return out.length() == indegree.size() ? out.toString() : "";
}

