export function alienOrderDfs(words: string[]): string {
  const graph = new Map<string, Set<string>>();
  for (const word of words) for (const ch of word) graph.set(ch, graph.get(ch) ?? new Set());
  for (let i = 0; i + 1 < words.length; i += 1) {
    const a = words[i], b = words[i + 1];
    if (a.length > b.length && a.startsWith(b)) return '';
    for (let j = 0; j < Math.min(a.length, b.length); j += 1) if (a[j] !== b[j]) { graph.get(a[j])!.add(b[j]); break; }
  }
  const color = new Map<string, number>();
  const out: string[] = [];
  function dfs(ch: string): boolean { if (color.get(ch) === 1) return false; if (color.get(ch) === 2) return true; color.set(ch, 1); for (const next of graph.get(ch) ?? []) if (!dfs(next)) return false; color.set(ch, 2); out.push(ch); return true; }
  return [...graph.keys()].every(dfs) ? out.reverse().join('') : '';
}

